// Hermes Output Enhancement alpha: read-only transcript styling, loaded through the documented disk-plugin contract.
// Generated by scripts/build-plugin.mjs from styles/p1-candidate.css. Do not add prompt or message processing.
const CSS = "[data-slot=\"aui_assistant-message-content\"] {\n  --readable-heading: light-dark(#704098, #9d7cd8);\n  --readable-emphasis: light-dark(#d68c27, #f5a742);\n  --readable-italic: light-dark(#b0851f, #e5c07b);\n}\n\n\n[data-slot=\"aui_assistant-message-content\"] .aui-md :is(h1, h2, h3, h4, h5, h6):not([data-slot='aui_markdown-alert'] *) {\n  color: var(--readable-heading);\n}\n\n[data-slot=\"aui_assistant-message-content\"] .aui-md :is(strong, [data-streamdown='strong']):not([data-slot='aui_markdown-alert'] *) {\n  color: var(--readable-emphasis);\n}\n\n[data-slot=\"aui_assistant-message-content\"] .aui-md em:not([data-slot='aui_markdown-alert'] *) {\n  color: var(--readable-italic);\n}\n\n\n\n\n[data-slot=\"aui_assistant-message-content\"] .aui-md-table {\n  border-color: var(--ui-stroke-secondary);\n}\n\n[data-slot=\"aui_assistant-message-content\"] .aui-md-table :is(th, td) {\n  padding: 0.625em 0.75em;\n  vertical-align: top;\n  line-height: 1.55;\n  overflow-wrap: anywhere;\n  border-inline-end: 1px solid var(--ui-stroke-secondary);\n  border-block-end: 1px solid var(--ui-stroke-secondary);\n}\n\n[data-slot=\"aui_assistant-message-content\"] .aui-md-table :is(th, td):last-child {\n  border-inline-end: 0;\n}\n\n[data-slot=\"aui_assistant-message-content\"] .aui-md-table tbody > tr:last-child > td {\n  border-block-end: 0;\n}\n\n[data-slot=\"aui_assistant-message-content\"] .aui-md-table th {\n  font-size: var(--conversation-text-font-size);\n}\n\n\n[data-slot=\"aui_assistant-message-content\"] .aui-md-table th > span:first-child {\n  white-space: normal;\n  overflow: visible;\n  text-overflow: clip;\n}\n\n\n[data-slot=\"aui_assistant-message-content\"] .aui-md-table table:not(:has(> colgroup)):has(> thead > tr > th:nth-child(2):last-child) {\n  table-layout: fixed;\n}\n\n[data-slot=\"aui_assistant-message-content\"] .aui-md-table table:not(:has(> colgroup)):has(> thead > tr > th:nth-child(2):last-child) th:first-child {\n  width: 27%;\n}\n\n\n[data-slot=\"aui_assistant-message-content\"] .aui-md-table table:has(> thead > tr > th:nth-child(3)) :is(th, td) {\n  min-width: 7em;\n}"
const STYLE_ATTRIBUTE = 'data-hermes-output-enhancement'
const ID = 'hermes-output-enhancement'

export default {
  id: ID,
  name: 'Hermes Output Enhancement',
  description: 'Enhances how existing Markdown in assistant replies is displayed — headings, bold and italic text get theme-aware light/dark colors; tables get a more readable layout. Inline code keeps the native Hermes styling. Display only: reply content is never modified; no model calls, session reads or history writes. Off by default; toggle in Settings → Capabilities → Plugins.',
  defaultEnabled: false,
  register(ctx) {
    if (typeof ctx?.onDispose !== 'function') {
      throw new Error('Hermes Output Enhancement requires the documented onDispose lifecycle API.')
    }
    if (document.head.querySelector('style[' + STYLE_ATTRIBUTE + '="' + ID + '"]')) {
      throw new Error('Hermes Output Enhancement is already active; disable the previous instance before reloading.')
    }
    const style = document.createElement('style')
    style.setAttribute(STYLE_ATTRIBUTE, ID)
    style.textContent = CSS
    ctx.onDispose(() => style.remove())
    document.head.append(style)
  }
}
